# frozen_string_literal: true

module IncidentIoGenerator
  # Renders the templates and writes the generated files.
  class Writer
    TEMPLATES = File.expand_path("../templates", __dir__)
    HEADER = <<~RUBY.chomp
      # This file is generated by `rake generate` from openapi/openapi.json.
      # Do not edit it by hand.
    RUBY
    # Single generated files and the template each is rendered from.
    INDEX_FILES = {
      "lib/incident_io/models.rb" => "models_index.rb",
      "lib/incident_io/resources.rb" => "resources_index.rb",
      "sig/incident_io/resources.rbs" => "resources_index.rbs",
      "lib/incident_io/webhook_events.rb" => "webhook_events.rb",
      "sig/incident_io/webhook_events.rbs" => "webhook_events.rbs",
      "lib/incident_io/audit_log_entries.rb" => "audit_log_entries.rb",
      "sig/incident_io/audit_log_entries.rbs" => "audit_log_entries.rbs"
    }.freeze
    # Generated paths, relative to the repository root. Removed before each
    # run so files for deleted schemas or tags don't linger.
    GENERATED = [
      "lib/incident_io/models",
      "lib/incident_io/resources",
      "sig/incident_io/models",
      "sig/incident_io/resources",
      *INDEX_FILES.keys,
      "spec/fixtures/operations.json",
      "spec/fixtures/allowed_values.json"
    ].freeze
    # Keep method signatures on one line up to this width.
    MAX_LINE = 110

    attr_reader :api

    def initialize(api, root)
      @api = api
      @root = root
    end

    # Writes every file and returns their paths relative to the root.
    def write
      GENERATED.each { |path| FileUtils.rm_rf(File.join(@root, path)) }

      files = INDEX_FILES.transform_values { |template| render(template) }
      files["spec/fixtures/operations.json"] = "#{JSON.pretty_generate(operations_manifest)}\n"
      files["spec/fixtures/allowed_values.json"] = "#{JSON.pretty_generate(allowed_values_manifest)}\n"
      api.models.each do |model|
        files["lib/incident_io/models/#{model.file_name}.rb"] = render("model.rb", model:)
        files["sig/incident_io/models/#{model.file_name}.rbs"] = render("model.rbs", model:)
      end
      api.resources.each do |resource|
        files["lib/incident_io/#{resource.file_path}.rb"] = render("resource.rb", resource:)
        files["sig/incident_io/#{resource.file_path}.rbs"] = render("resource.rbs", resource:)
      end

      files.each do |path, source|
        full = File.join(@root, path)
        FileUtils.mkdir_p(File.dirname(full))
        File.write(full, source)
      end
      files.keys
    end

    # Turns free text into Ruby comment lines at the given indent. Returns
    # "" for blank text.
    def comment(text, indent)
      return "" if text.nil? || text.strip.empty?

      pad = " " * indent
      text.strip.lines.map { |line| line.rstrip.empty? ? "#{pad}#\n" : "#{pad}# #{line.rstrip}\n" }.join
    end

    # YARD docs for a generated method: a one-line summary, then the full
    # description when there's more to it.
    def method_docs(op, indent)
      description = op_text(op)
      short = method_summary(op)
      lines = [short, ""]
      lines += [description, ""] unless [short, "#{short}."].include?(description)
      endpoint = "Endpoint: `#{op.http_method.upcase} #{op.path}`."
      endpoint += " Scopes: #{op.scopes.join(", ")}." if op.scopes.any?
      lines << endpoint
      lines << "Does not use your API key; pass the alert source token instead." if op.no_auth
      lines << ""
      if op.deprecated
        lines << (op.replacement ? "@deprecated Use `#{op.replacement}` instead." : "@deprecated incident.io has deprecated this endpoint.")
      end
      (op.path_params + op.keyword_params).each do |p|
        detail = sentence(p.description)
        detail = [detail, "Generated when not given."].compact.join(" ") if p.default
        type = Types.yard_type(p.schema, accepts_hash: true)
        lines << "@param #{p.name} [#{type}]#{" #{detail}" if detail}"
      end
      lines << "@param request_options [Hash] Per-call options, see IncidentIo::Client#request."
      lines << "@return [#{op.result.yard}]"
      comment(lines.join("\n"), indent)
    end

    # The one-line summary of a generated method, for its YARD and RBS docs.
    def method_summary(op)
      summary(op_text(op), "Calls #{op.operation_id}")
    end

    # An operation's description, or its summary when it has none.
    def op_text(op)
      (op.description || op.summary).to_s.strip
    end

    # The parameter list of a generated method.
    def signature(op, indent)
      args = op.path_params.map(&:name)
      op.keyword_params.each do |p|
        args << if p.required then "#{p.name}:"
        elsif p.default then "#{p.name}: #{p.default}"
        elsif p.not_given? then "#{p.name}: NOT_GIVEN"
        else "#{p.name}: nil"
        end
      end
      args << "request_options: {}"
      wrap("def #{op.method_name}(", args, ")", indent)
    end

    # The body of a generated method: one request or paginate call.
    def call(op, indent)
      paginated = op.result.kind == :paginated
      args = paginated ? [] : [":#{op.http_method}"]
      args << path_expression(op)
      args << "items_key: #{op.result.items_key.inspect}" if paginated
      args << "query: #{hash_expression(op.query_params, indent + 2)}" if op.query_params.any?
      args << "body: #{body_expression(op.body_params, indent + 2)}" if op.body
      args << "idempotent: true" if op.idempotent
      args << "unwrap: #{op.result.unwrap.inspect}" if op.result.unwrap
      args << "model: #{op.result.model}" if op.result.model
      args << "request_options:"
      "#{" " * indent}#{one_per_line(paginated ? "paginate(" : "request(", args, ")", indent)}"
    end

    # Ruby source of a hash literal, a key per line when it doesn't fit.
    def hash_expression(params, indent)
      return "{}" if params.empty?

      wrap("{", params.map { |p| "#{p.name}:" }, "}", indent, reserve: 10)
    end

    # Request body source: `given({...})` drops arguments that weren't passed.
    def body_expression(params, indent)
      return "{}" if params.empty?

      "given(#{hash_expression(params, indent)})"
    end

    def path_expression(op)
      return op.path.inspect if op.path_params.empty?

      template = op.path.gsub("%", "%%").gsub(/\{\w+\}/, "%s")
      "path(#{template.inspect}, #{op.path_params.map(&:name).join(", ")})"
    end

    # A hash key in `Model.define(...)`.
    def model_key(name)
      (Naming.safe_identifier?(name) || Naming::RUBY_KEYWORDS.include?(name)) ? "#{name}:" : "#{name.inspect}:"
    end

    # An RBS method definition, one line when it fits:
    #   def show: (String id, ?request_options: request_options) -> Models::X
    def rbs_def(name, params, returns, indent)
      wrap("def #{name}: (", params, ") -> #{returns}", indent)
    end

    # RBS parameters for a generated resource method.
    def rbs_params(op)
      params = op.path_params.map { |p| "String #{p.name}" }
      op.keyword_params.each do |p|
        type = Types.rbs_type(p.schema, input: true)
        params << if p.required then "#{p.name}: #{type}"
        elsif p.default then "?#{p.name}: #{type}"
        elsif p.not_given? then "?#{p.name}: #{Types.rbs_optional("#{type} | NotGiven")}"
        else "?#{p.name}: #{Types.rbs_optional(type)}"
        end
      end
      params << "?request_options: request_options"
    end

    # RBS keyword parameters for a model's fields, all optional.
    def rbs_fields(model)
      model.fields.map { |f| "?#{f.member}: #{Types.rbs_optional(f.rbs)}" }
    end

    # A one-line YARD summary: the first sentence without its full stop,
    # shortened to fit in 80 characters. Uses the fallback for blank text.
    def summary(text, fallback)
      line = first_sentence(text.to_s.strip.gsub(/\s+/, " ")).to_s.sub(/[.:]+\z/, "")
      line = fallback if line.empty?
      return line if line.length < 80

      "#{line[0, 78].sub(/\s+\S*\z/, "")}…"
    end

    # Items between open and close on one line when they fit in MAX_LINE,
    # less reserve characters for what follows; otherwise one per line.
    def wrap(open, items, close, indent, reserve: 0)
      one_line = "#{open}#{items.join(", ")}#{close}"
      return one_line if indent + one_line.length + reserve <= MAX_LINE

      one_per_line(open, items, close, indent)
    end

    # Items between open and close, one per line, or just open and close
    # when there are none.
    def one_per_line(open, items, close, indent)
      return "#{open}#{close}" if items.empty?

      pad = " " * (indent + 2)
      "#{open}\n#{items.map { |item| "#{pad}#{item}" }.join(",\n")}\n#{" " * indent}#{close}"
    end

    # Ends text with a full stop unless it already ends a sentence.
    def sentence(text)
      return nil if text.nil?

      text.match?(/[.!?)]\z/) ? text : "#{text}."
    end

    # First sentence of a description, for short attribute docs.
    def first_sentence(text)
      return nil if text.nil?

      text[/\A.*?[.!?](?=\s|\z)/] || text
    end

    # What each generated resource method should do, for
    # spec/incident_io/generated_operations_spec.rb: how to call it, the
    # request it should send and what it should return. BreakingChanges
    # reads the arguments from it too.
    def operations_manifest
      api.resources.flat_map do |resource|
        resource.operations.map do |op|
          keyword_params = op.keyword_params.select(&:required)
          {
            "operation_id" => op.operation_id,
            # How the method is called, like "client.v2.incidents.list".
            "call" => op.full_name,
            "version" => resource.version.downcase,
            "resource" => resource.name,
            "method" => op.method_name,
            "deprecated" => op.deprecated,
            "http_method" => op.http_method,
            "path" => op.path,
            "path_args" => op.path_params.map { |p| "#{p.name}-value" },
            "keyword_args" => keyword_params.to_h { |p| [p.name, Types.sample_value(p.schema, p.name)] },
            # Every argument, optional ones too, with its YARD type.
            "arg_types" => (op.path_params + op.keyword_params).to_h do |p|
              [p.name, Types.yard_type(p.schema, accepts_hash: true)]
            end,
            "returns" => op.result.yard,
            "query_keys" => keyword_params.select { |p| p.location == :query }.map(&:name),
            "body_keys" => keyword_params.select { |p| p.location == :body }.map(&:name),
            "body" => op.body,
            # An optional body field to pass as nil, which should be sent as null.
            "null_body_key" => op.body_params.find(&:not_given?)&.name,
            "idempotency_key" => op.idempotent,
            "result" => {
              "kind" => op.result.kind.to_s,
              "unwrap" => op.result.unwrap,
              "items_key" => op.result.items_key,
              "model" => op.result.model_name,
              "depth" => op.result.depth
            }
          }
        end
      end
    end

    # The values each model field and each method argument is limited to,
    # and the operators each filter argument allows, for BreakingChanges.
    # Those without limits are left out.
    #
    # The spec names no operators for a filter that is keyed by an ID, like
    # `custom_field`, because they depend on the custom field. For these,
    # `example_operators` has the operators that the spec's examples show.
    def allowed_values_manifest
      fields = api.models.to_h { |model| [model.name, model.fields.map(&:limits).reduce({}, :merge)] }
      arguments = {}
      operators = {}
      example_operators = {}
      api.resources.each do |resource|
        resource.operations.each do |op|
          call = op.full_name
          params = op.path_params + op.keyword_params
          arguments[call] = params.map { |p| Types.limits(p.schema, p.name) }.reduce({}, :merge)
          operators[call] = params.to_h { |p| [p.name, Types.operators(p.description)] }.compact
          unnamed = op.query_params.select { |p| p.schema["type"] == "object" && !operators[call].key?(p.name) }
          example_operators[call] = unnamed.to_h do |p|
            [p.name, Types.example_operators(p.name, p.schema["example"], op.description)]
          end.reject { |_, shown| shown.empty? }
        end
      end
      {
        "fields" => fields, "arguments" => arguments, "operators" => operators, "example_operators" => example_operators
      }.transform_values do |limits|
        limits.reject { |_, values| values.empty? }
      end
    end

    private

    def render(name, **locals)
      @templates ||= {}
      template = @templates[name] ||= ERB.new(File.read(File.join(TEMPLATES, "#{name}.erb")), trim_mode: "-")
      template.result_with_hash(helpers: self, header: HEADER, api:, **locals)
    end
  end
end
